#!/usr/bin/env python3
"""Apply the actual Mixin transformer to all pinned target classes; verify generated bytecode."""
import json,os,subprocess,pathlib
from build import ROOT,REPO,RECRUITS

def main():
    libs=sorted((REPO/'server/libraries').rglob('*.jar'));asm=[p for p in libs if p.name.startswith('asm') and '9.9.1' in str(p)]
    patched=next(p for p in libs if p.name=='forge-1.20.1-47.4.23-server.jar');game=next(p for p in libs if p.name=='server-1.20.1-20230612.114412-srg.jar')
    guard=REPO/'server/mods/empirecraft-claim-guard-1.0.1.jar'
    deps=[*asm,patched,game,ROOT/'dist/empirecraft-recruits-integration-1.0.0.jar',RECRUITS,*([guard] if guard.exists() else []),*libs]
    cp=os.pathsep.join(map(str,deps));out=ROOT/'build/mixin-tests';out.mkdir(parents=True,exist_ok=True)
    home=pathlib.Path(os.environ.get('JAVA_HOME','/workspace/toolchains/jdk-17.0.16+8'))
    subprocess.run([str(home/'bin/javac'),'--release','17','-proc:none','-encoding','UTF-8','-cp',cp,'-d',str(out),*map(str,(ROOT/'tests/guardtest').glob('*.java'))],check=True)
    services=out/'META-INF/services';services.mkdir(parents=True,exist_ok=True);(services/'org.spongepowered.asm.service.IMixinService').write_text('guardtest.OfflineMixinService\n');(services/'org.spongepowered.asm.service.IGlobalPropertyService').write_text('guardtest.OfflineProperties\n')
    packets=json.loads((ROOT/'build/packet-targets.json').read_text());listing=out/'targets.txt';listing.write_text('\n'.join(packets)+'\n')
    args=[str(listing)]
    if guard.exists():
        config='guard-projectile-test.mixins.json'
        (out/config).write_text(json.dumps({'required':True,'minVersion':'0.8.5','package':'ua.empirecraft.claimguard.mixin','compatibilityLevel':'JAVA_17','mixins':['ProjectileOwnerMixin'],'injectors':{'defaultRequire':1}}))
        args.append(config)
    subprocess.run([str(home/'bin/java'),'-ea','-cp',str(out)+os.pathsep+cp,'guardtest.ArmyMixinTest',*args],check=True)
if __name__=='__main__':main()
